"""Fail if public/ is out of date with frontend/ (public/ is generated by export_static.py).

Usage (from repo root): python scripts/check_static.py
Exit code 1 lists every file that differs, is missing from public/, or is stale in public/.
public/data/ (the exported featured views) is not compared here.
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
FRONTEND = ROOT / "frontend"
PUBLIC = ROOT / "public"
SKIP_DIRS = {"__pycache__"}


def _files(base: Path, exclude_top: set[str] = frozenset()) -> set[str]:
    out = set()
    for f in base.rglob("*"):
        rel = f.relative_to(base)
        if not f.is_file() or rel.parts[0] in exclude_top or SKIP_DIRS & set(rel.parts):
            continue
        out.add(rel.as_posix())
    return out


def drift() -> list[str]:
    src = _files(FRONTEND)
    dst = _files(PUBLIC, exclude_top={"data"})
    problems = [f"missing in public/: {p}" for p in sorted(src - dst)]
    problems += [f"stale in public/ (not in frontend/): {p}" for p in sorted(dst - src)]
    problems += [f"differs: {p}" for p in sorted(src & dst)
                 if (FRONTEND / p).read_bytes() != (PUBLIC / p).read_bytes()]
    return problems


def main() -> int:
    problems = drift()
    if not problems:
        print("public/ matches frontend/")
        return 0
    print("public/ is out of date. Run: python scripts/export_static.py", file=sys.stderr)
    for p in problems:
        print(f"  {p}", file=sys.stderr)
    return 1


if __name__ == "__main__":
    sys.exit(main())
